const BANK = [{"id": 1, "q": "La determinación de los procesos de fabricación y tiempos precisos de las actividades necesarias para la elaboración de los productos corresponde al departamento de", "opts": {"A": "Ingeniería de diseño industrial.", "B": "Ingeniería de Procesos.", "C": "Calidad.", "D": "Marketing."}, "correct": "B", "tema": "Organización de la empresa", "src": "banco", "exp": "Ingeniería de Procesos (Métodos y Tiempos) es quien define cómo se fabrica cada producto y cuánto tarda cada operación. Diseño define el producto; Calidad lo controla; Marketing lo vende."}, {"id": 2, "q": "Los requisitos de participación en un proyecto, el plazo de presentación de ofertas, fecha y lugar de apertura de plicas, fecha de comienzo de la obra, plazo de entrega, etc. en el pliego de condiciones, se encuadran dentro de las condiciones…", "opts": {"A": "generales.", "B": "específicas.", "C": "ambas.", "D": "ninguna de ellas."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Plazos, apertura de plicas, fechas de inicio/entrega… son condiciones GENERALES (administrativas), comunes a cualquier obra. Las específicas son las técnicas (materiales, calidades)."}, {"id": 3, "q": "La definición y tamaño de un proyecto, usos del producto, el estado de la técnica y las fuentes de información, dentro de un proyecto técnico, son pasos de la…", "opts": {"A": "Fase 0.- Orden de Magnitud (Prefase).", "B": "Fase 1.- Estudio Preliminar o de Viabilidad.", "C": "Fase 2.- Anteproyecto o Proyecto Básico.", "D": "Fase 3.- Proyecto o Diseño Detallado."}, "correct": "A", "tema": "Propiedad industrial y patentes", "src": "banco", "exp": "Definir el proyecto, sus usos, el estado de la técnica y las fuentes de información es lo primero de todo: la Fase 0 (Orden de Magnitud o prefase), donde solo se acota el problema."}, {"id": 4, "q": "Los modelos que contribuyen al planteamiento y resolución de problemas, mediante una representación visual que permite el establecimiento de relaciones entre elementos y la síntesis de éstos que conduce a la construcción del conjunto, reciben el nombre de…", "opts": {"A": "modelos icónicos.", "B": "modelos analógicos. 17", "C": "modelos simbólicos.", "D": "de las tres maneras mencionadas."}, "correct": "A", "tema": "General", "src": "banco", "exp": "Los modelos ICÓNICOS son representaciones visuales/físicas (maquetas, renders) que dejan ver la forma y las relaciones del conjunto. Los analógicos imitan comportamiento; los simbólicos son matemáticos."}, {"id": 5, "q": "La Memoria es un documento descriptivo del proyecto. Cuál de los elementos que se mencionan no se incluyen en la memoria.", "opts": {"A": "Enunciado del problema que se pretende resolver.", "B": "Justificación de la necesidad del proyecto.", "C": "Forma pormenorizada del producto objeto del proyecto y sus componentes.", "D": "Cálculos y planos constructivos."}, "correct": "D", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "La Memoria es DESCRIPTIVA (qué y por qué). Los cálculos y planos constructivos van en sus propios documentos (Cálculos y Planos), no en la memoria."}, {"id": 6, "q": "Cada pieza o elemento aislado de un conjunto o subconjunto…", "opts": {"A": "se dibujará en plano independiente.", "B": "podrán dibujarse varias piezas en el mismo plano si son pequeñas.", "C": "se podrán dibujar en el mismo plano si son de la misma familia de piezas.", "D": "se deja a criterio de quien proyecta."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Cada pieza se dibuja en plano independiente para poder fabricarla sin ambigüedad. No se agrupan aunque sean pequeñas o de la misma familia."}, {"id": 7, "q": "En un proyecto, las fases de Tramitación y de Recepción, pertenecen al grupo de fases…", "opts": {"A": "creativas.", "B": "de construcción.", "C": "de explotación.", "D": "de todas las anteriores."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Tramitación y Recepción son fases de CONSTRUCCIÓN (la obra ya se está gestionando/entregando), no creativas. Las creativas son las de diseño."}, {"id": 8, "q": "En un proyecto, las fases de realización o de Ejecución y de Adjudicación o Contratación, pertenecen al grupo de fases…", "opts": {"A": "creativas.", "B": "de construcción. 18", "C": "de explotación.", "D": "de todas las anteriores."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Ejecución y Adjudicación/Contratación pertenecen al grupo de CONSTRUCCIÓN: ya no se diseña, se contrata y se ejecuta la obra."}, {"id": 9, "q": "El conjunto estructural que forman las etapas a resolver en cualquier proyecto de ingeniería, y que únicamente fijan lo que hay que hacer, se denomina…", "opts": {"A": "macroestructura del proyecto.", "B": "macroestructura de la fase.", "C": "microestructura del proyecto.", "D": "microestructura de la fase."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "La \"macroestructura\" define a alto nivel las fases del proyecto (estudios preliminares, diseño, construcción, etc.), estableciendo *qué* debe hacerse."}, {"id": 10, "q": "La recopilación de antecedentes, la revisión de la información, la organización de la información, la descripción del mercado y su tamaño, el estudio del producto o productos y del proceso o procesos, etc., en el caso de un proyecto de una planta industrial, son pasos de la…", "opts": {"A": "Fase 0.- Orden de Magnitud (Prefase).", "B": "Fase 1.- Estudio Preliminar o de Viabilidad.", "C": "Fase 2.- Anteproyecto o Proyecto Básico.", "D": "Fase 3.- Proyecto o Diseño Detallado."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Recopilar antecedentes, estudiar el mercado y el producto/proceso es la Fase 1 (Estudio Preliminar o de Viabilidad): se reúne y organiza la información para ver si el proyecto es viable."}, {"id": 11, "q": "La descripción del mercado, estimación del volumen de producción, examen de la propiedad industrial, estudio del producto y factores del diseño, son entre otros en el caso de un proyecto de un producto industrial, pasos que componen la…", "opts": {"A": "Fase 0.- Orden de Magnitud (Prefase).", "B": "Fase 1.- Estudio Preliminar o de Viabilidad.", "C": "Fase 2.- Anteproyecto o Proyecto Básico.", "D": "Fase 3.- Proyecto o Diseño Detallado."}, "correct": "B", "tema": "Propiedad industrial y patentes", "src": "banco", "exp": "Describir el mercado, estimar producción, examinar la propiedad industrial y estudiar el producto es la Fase 1 (Estudio Preliminar o de Viabilidad)."}, {"id": 12, "q": "Los modelos que son abstracciones abreviadas de las partes relevantes y cuantificables de un problema, reciben el nombre de…", "opts": {"A": "modelos icónicos.", "B": "modelos analógicos.", "C": "modelos simbólicos.", "D": "de las tres maneras mencionadas."}, "correct": "C", "tema": "Evaluación económica", "src": "banco", "exp": "Los modelos SIMBÓLICOS son abstracciones abreviadas y cuantificables (fórmulas, ecuaciones) de las partes relevantes del problema."}, {"id": 13, "q": "La fase que tiene por objetivo desarrollar los documentos precisos para la definición constructiva del producto y su valoración económica se denomina…", "opts": {"A": "Fase 0.- Orden de Magnitud (Prefase).", "B": "Fase 1.- Estudio Preliminar o de Viabilidad.", "C": "Fase 2.- Anteproyecto o Proyecto Básico.", "D": "Fase 3.- Proyecto o Diseño Detallado."}, "correct": "D", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Desarrollar los documentos para la definición constructiva y la valoración económica es la Fase 3 (Proyecto o Diseño Detallado): el documento definitivo para construir."}, {"id": 14, "q": "Los documentos escritos, en un proyecto, se presentan en papel tamaño…", "opts": {"A": "folio.", "B": "formato UNE A4.", "C": "cualquiera de ambos.", "D": "cualquiera dependiendo del proyecto. 20"}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Los documentos escritos se presentan en formato normalizado UNE A4 (no folio)."}, {"id": 15, "q": "El documento en el que se refleja de modo gráfico la forma, disposición, situación, dimensiones, calidades, tolerancias y materiales a utilizar para la realización y montaje del producto objeto de un proyecto es el documento…", "opts": {"A": "memoria.", "B": "planos.", "C": "mediciones.", "D": "cálculos."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "El documento gráfico con forma, dimensiones, calidades, tolerancias y materiales para fabricar/montar es PLANOS."}, {"id": 16, "q": "Las bases de concurso subasta y que se incluyen entre los requisitos que debe cumplir un proyecto según el pliego de condiciones, son consideradas…", "opts": {"A": "condiciones generales y administrativas.", "B": "condiciones específicas.", "C": "el pliego de condiciones no considera dichos requisitos.", "D": "ninguna de las anteriores."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Las bases de concurso-subasta son condiciones GENERALES y administrativas (cómo se concursa), no técnicas."}, {"id": 17, "q": "La calidad de los materiales que integran un proyecto así como la garantía que debe acompañar al producto obtenido, en el pliego de condiciones, se encuadran dentro de las condiciones…", "opts": {"A": "generales.", "B": "específicas.", "C": "ambas.", "D": "ninguna de ellas."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "La calidad de los materiales y la garantía del producto son condiciones ESPECÍFICAS (técnicas, propias de ese proyecto)."}, {"id": 18, "q": "Los conceptos diseño y proyecto son…", "opts": {"A": "sinónimos.", "B": "distintos.", "C": "depende de la complejidad del estudio.", "D": "depende del valor económico del mismo. 21"}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Diseño y proyecto son conceptos DISTINTOS: el diseño define el producto; el proyecto es la actividad global que lo desarrolla y lo lleva a término."}, {"id": 19, "q": "Convertir las especificaciones que debe cumplir el producto, en una descripción completa y clara del mismo, que consiste en esbozar, dibujar o delinear alguna pieza o algún conjunto recibe el nombre de…", "opts": {"A": "diseño.", "B": "proyecto.", "C": "cualquiera de las dos anteriores.", "D": "según la complejidad y coste previsto del estudio de que se trate."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "DISEÑO es convertir las especificaciones en una descripción del producto, esbozando o delineando piezas y conjuntos."}, {"id": 20, "q": "Una actividad más genérica y compleja, que exige la aplicación económica de recursos y la puesta en juego de conocimientos técnicos muy variados, para desarrollar la solución óptima a la necesidad planteada recibe el nombre de…", "opts": {"A": "diseño.", "B": "proyecto.", "C": "cualquiera de las dos anteriores.", "D": "según la complejidad y coste previsto del estudio de que se trate."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "PROYECTO es la actividad más amplia y compleja, que aplica recursos económicos y conocimientos técnicos variados para dar la solución óptima."}, {"id": 21, "q": "En un proyecto, las fases Anteproyecto o Proyecto Básico y Proyecto o Diseño Detallado, pertenecen al grupo de fases…", "opts": {"A": "creativas.", "B": "de construcción.", "C": "de explotación.", "D": "de todas las anteriores. 22"}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Anteproyecto y Proyecto Detallado son fases CREATIVAS (todavía se está diseñando, antes de construir)."}, {"id": 22, "q": "Al conjunto de etapas, subetapas y pasos que fijan cómo ha de resolverse la fase para un proyecto determinado, se le denomina…", "opts": {"A": "macroestructura del proyecto.", "B": "macroestructura de la fase.", "C": "microestructura del proyecto.", "D": "microestructura de la fase."}, "correct": "D", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "La MICROESTRUCTURA de la fase fija el CÓMO (etapas, subetapas y pasos para resolverla). La macroestructura fija solo el QUÉ."}, {"id": 23, "q": "Permitir la eliminación de aquellas ideas y propuestas que no tienen ninguna viabilidad, poder llegar a plantear el problema adecuadamente y desechar propuestas que no tienen viabilidad, son objetivos de la…", "opts": {"A": "Fase 0.- Orden de Magnitud (Prefase).", "B": "Fase 1.- Estudio Preliminar o de Viabilidad.", "C": "Fase 2.- Anteproyecto o Proyecto Básico.", "D": "Fase 3.- Proyecto o Diseño Detallado."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Eliminar ideas inviables y plantear bien el problema son objetivos de la Fase 0 (Orden de Magnitud): se criba antes de invertir esfuerzo."}, {"id": 24, "q": "Conocer el proyecto en su conjunto, ver posibles soluciones alternativas y estudiar la viabilidad de las mismas, son objetivos de la…", "opts": {"A": "Fase 0.- Orden de Magnitud (Prefase).", "B": "Fase 1.- Estudio Preliminar o de Viabilidad.", "C": "Fase 2.- Anteproyecto o Proyecto Básico.", "D": "Fase 3.- Proyecto o Diseño Detallado."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Conocer el proyecto en conjunto, ver alternativas y estudiar su viabilidad son objetivos de la Fase 1 (Estudio Preliminar o de Viabilidad)."}, {"id": 25, "q": "En el caso de un proyecto técnico, seleccionar la solución conveniente, desarrollarla y definirla, mejorar los diseños previos y conocer la rentabilidad del proyecto, son los objetivos de…", "opts": {"A": "Fase 0.- Orden de Magnitud (Prefase).", "B": "Fase 1.- Estudio Preliminar o de Viabilidad.", "C": "Fase 2.- Anteproyecto o Proyecto Básico.", "D": "Fase 3.- Proyecto o Diseño Detallado. 23"}, "correct": "C", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Seleccionar y desarrollar la solución, mejorar diseños previos y conocer la rentabilidad son objetivos de la Fase 2 (Anteproyecto o Proyecto Básico)."}, {"id": 26, "q": "La fase más creativa y más difícil de la que se responsabilizan de ella mejores expertos de la organización, y en la que se pone a su disposición todos los recursos necesarios, es la…", "opts": {"A": "Fase 0.- Orden de Magnitud (Prefase).", "B": "Fase 1.- Estudio Preliminar o de Viabilidad.", "C": "Fase 2.- Anteproyecto o Proyecto Básico.", "D": "Fase 3.- Proyecto o Diseño Detallado."}, "correct": "C", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "La fase más creativa y difícil, con los mejores expertos y todos los recursos, es la Fase 2 (Anteproyecto): aquí se concibe la solución."}, {"id": 27, "q": "Los modelos que se utilizan para simular el comportamiento de un sistema de difícil estudio directo, mediante otro sistema que pueda reproducir las características y circunstancias del primero en condiciones más sencillas, reciben el nombre de…", "opts": {"A": "modelos icónicos.", "B": "modelos analógicos.", "C": "modelos simbólicos.", "D": "de las tres maneras mencionadas."}, "correct": "B", "tema": "Normativa (CTE, incendios, seguridad)", "src": "banco", "exp": "Los modelos ANALÓGICOS simulan el comportamiento de un sistema difícil mediante otro análogo más sencillo que reproduce sus características."}, {"id": 28, "q": "El Proyecto en el que quedan definidos perfectamente todos y cada uno de los subsistemas, componentes y partes que integran el proyecto, de tal manera que los documentos que lo desarrollan han de ser suficientes para llevarlo a la práctica, ya sea bajo la dirección de los mismos proyectistas o por otro equipo de ingeniería distinto, se denomina…", "opts": {"A": "Anteproyecto.", "B": "Proyecto básico.", "C": "Proyecto detallado.", "D": "Cualquiera de las tres anteriores según en qué fase o etapa se encuentre. 24"}, "correct": "C", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Cuando todo queda definido para poder construirlo (incluso por otro equipo), es el Proyecto DETALLADO."}, {"id": 29, "q": "En un proyecto, qué elemento no es necesario para la definición constructiva del producto y su valoración económica.", "opts": {"A": "Memoria.", "B": "Modelo.", "C": "Planos.", "D": "Pliego de condiciones."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "El MODELO no es necesario para la definición constructiva. Los documentos imprescindibles son Memoria, Planos, Pliego de condiciones y Presupuesto."}, {"id": 30, "q": "Las condiciones que figuran en el pliego de condiciones de un proyecto y que son independientes del tipo de proyecto, reciben el nombre de…", "opts": {"A": "generales.", "B": "específicas.", "C": "ambas.", "D": "ninguna de ellas."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Las condiciones independientes del tipo de proyecto son las GENERALES (las técnicas propias serían las específicas)."}, {"id": 31, "q": "En un proyecto, las fases Orden de Magnitud y Estudio Preliminar o de Viabilidad, pertenecen al grupo de fases…", "opts": {"A": "creativas.", "B": "de construcción.", "C": "de explotación.", "D": "de todas las anteriores."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Orden de Magnitud y Estudio Preliminar son fases CREATIVAS (la parte de concepción/diseño, antes de construir)."}, {"id": 32, "q": "Los medios que utiliza un ingeniero y que le permiten conocer las dificultades de un proyecto antes de que se construya, reciben el nombre de…", "opts": {"A": "modelos.", "B": "maquetas.", "C": "planos.", "D": "estudios."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Los MODELOS permiten al ingeniero anticipar las dificultades de un proyecto antes de construirlo (las maquetas y planos son tipos concretos)."}, {"id": 33, "q": "La lista de despiezo es característica de un…", "opts": {"A": "plano de conjunto.", "B": "plano de subconjunto.", "C": "de ambos.", "D": "de todos los planos. 26"}, "correct": "C", "tema": "Normativa (CTE, incendios, seguridad)", "src": "banco", "exp": "La lista de despiece acompaña tanto a planos de conjunto como de subconjunto: en AMBOS, para identificar las piezas."}, {"id": 34, "q": "El programa reticular PERT (Program Evaluation and Review Technique), creado en 1957 por la Marina de los EE.UU. de América, para planificar, programar y controlar el proyecto de construcción de submarinos atómicos equipados con proyectiles Polaris, permitió un adelanto sobre el tiempo previsto de…", "opts": {"A": "un año.", "B": "dos años.", "C": "cinco años.", "D": "no permitió adelanto del fin del proyecto."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "El PERT permitió un adelanto de DOS años en el proyecto Polaris de la Marina de EE.UU."}, {"id": 35, "q": "El programa reticular PERT…", "opts": {"A": "estima la duración de las actividades, de forma probabilista para un nivel de coste dado.", "B": "maneja tiempos conocidos de otro proyecto anterior.", "C": "establece el tiempo en base a los deseos del cliente.", "D": "determina el tiempo mediante sistemas convencionales de análisis de tiempos (desglose en microoperaciones)."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "El PERT estima la duración de las actividades de forma PROBABILISTA para un nivel de coste dado (usa tres tiempos: optimista, probable y pesimista)."}, {"id": 36, "q": "Una vez iniciada una obra, el principal responsable de la misma es…", "opts": {"A": "la Propiedad.", "B": "el Autor del Proyecto.", "C": "el Director del Proyecto.", "D": "el Contratista General."}, "correct": "C", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Una vez iniciada la obra, el principal responsable es el Director del Proyecto (dirige y supervisa su ejecución)."}, {"id": 37, "q": "En el programa reticular CPM (Método del Camino Crítico) se realizan dos estimaciones de la duración de las actividades y junto a ellas las correspondientes estimaciones del coste. En la segunda combinación de ellas no se repara en el coste a fin de reducir al mínimo la duración de la actividad y recibe el nombre de…", "opts": {"A": "coste normal.", "B": "duración acelerada.", "C": "cualquiera de las anteriores.", "D": "ninguna de las anteriores."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "La combinación que reduce al máximo la duración sin reparar en el coste es la DURACIÓN ACELERADA (frente a la normal, que optimiza coste)."}, {"id": 38, "q": "En el programa reticular PERT (Evaluación y Revisión Técnica de Programas)…", "opts": {"A": "se estima la duración para un nivel de coste dado.", "B": "se relaciona duración y coste.", "C": "ambos.", "D": "ninguno de los anteriores."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "En el PERT se estima la duración para un nivel de coste dado. Relacionar duración y coste (intercambio tiempo-coste) es propio del CPM."}, {"id": 39, "q": "Qué actividades reciben el nombre de críticas en un programa o camino crítico según el método de los potenciales de Bernard Roy.", "opts": {"A": "Las actividades que pueden empezar antes de la fecha máxima.", "B": "Las actividades que empiezan antes de la fecha mínima.", "C": "Las actividades cuya holgura total es nula.", "D": "Las actividades que empiezan después de la fecha mínima."}, "correct": "C", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Las actividades CRÍTICAS son las de holgura total NULA: cualquier retraso suyo retrasa todo el proyecto (forman el camino crítico)."}, {"id": 40, "q": "En un programa o camino crítico según el método de los potenciales de Bernard Roy, en el caso de actividades convergentes se debe tomar…", "opts": {"A": "el de mayor valor.", "B": "el de menor valor.", "C": "la media aritmética de los valores de cada actividad.", "D": "cualquier valor elegido entre el máximo y el mínimo."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "En actividades convergentes, al calcular las fechas mínimas se toma el MAYOR valor (hay que esperar a que terminen todas las que llegan)."}, {"id": 41, "q": "Una planificación representada por un diagrama GANTT lo es mediante un…", "opts": {"A": "diagrama de barras.", "B": "diagrama reticular.", "C": "diagrama grafo.", "D": "ninguno de los anteriores."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "El diagrama de Gantt es un diagrama de BARRAS (cada actividad, una barra sobre el calendario)."}, {"id": 42, "q": "La característica más importante de la planificación de un proyecto es…", "opts": {"A": "estimar la duración.", "B": "determinar las relaciones de precedencia.", "C": "la anticipación en el tiempo.", "D": "el seguimiento y el control del proyecto."}, "correct": "C", "tema": "Normativa (CTE, incendios, seguridad)", "src": "banco", "exp": "Lo más importante de planificar es la ANTICIPACIÓN en el tiempo: prever para poder decidir y controlar antes de que ocurran los problemas."}, {"id": 43, "q": "La técnica de planificación más utilizada, mediante representación gráfica es…", "opts": {"A": "el diagrama de barras de Gantt.", "B": "el diagrama reticular o grafo.", "C": "cualquiera de los anteriores.", "D": "ninguno de los anteriores. Será un gráfico específico para cada proyecto."}, "correct": "C", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "La técnica gráfica más utilizada es CUALQUIERA de las dos: el diagrama de barras de Gantt o el diagrama reticular/grafo, según convenga."}, {"id": 44, "q": "Un diagrama de planificación GANTT…", "opts": {"A": "es muy útil como instrumento de planificación y control.", "B": "presenta limitaciones en cuanto a falta de información sobre la interdependencia de las distintas actividades, sobre todo en la planificación de proyectos complejos.", "C": "es muy práctico en el caso de que haya que tomar acciones correctivas en base a las desviaciones que se produzcan.", "D": "las tres son correctas."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "La limitación del Gantt es que NO muestra la interdependencia entre actividades, lo que se nota mucho en proyectos complejos."}, {"id": 45, "q": "Las diferencias entre los distintos diagramas reticulares cuyas fases son: 1º. Inventario o desglose de actividades agrupadas por especialidades. 2º. Relaciones de orden entre las operaciones. 3º. Análisis e interpretación de resultados. se encuentran fundamentalmente en…", "opts": {"A": "la fase primera.", "B": "la fase segunda.", "C": "la fase tercera.", "D": "todas las fases."}, "correct": "C", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Las diferencias entre los distintos diagramas reticulares están en la 3ª fase: el análisis e interpretación de resultados (el inventario y las relaciones son comunes)."}, {"id": 46, "q": "Un diagrama grafo…", "opts": {"A": "no se aplica nunca a los proyectos repetitivos.", "B": "no es utilizado por los sistemas de programación reticular.", "C": "exige la consideración de un conjunto de elementos entre los que existen ligaduras orientadas.", "D": "no se emplea si se trata de un conjunto de elementos entre los que existen ligaduras orientadas."}, "correct": "C", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Un grafo exige un conjunto de elementos con LIGADURAS ORIENTADAS (relaciones de precedencia con sentido), que es justo lo que representa."}, {"id": 47, "q": "La determinación de las fechas mínimas en un programa o camino crítico según el método de los potenciales de Bernard Roy y que se escriben debajo de su recuadro…", "opts": {"A": "se determinan de derecha a izquierda.", "B": "se determinan de izquierda a derecha.", "C": "se determinan iniciando por las actividades de valor más elevado.", "D": "se determinan iniciando por las actividades de menor valor."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Las fechas MÍNIMAS (más tempranas) se calculan de IZQUIERDA a DERECHA (cálculo de ida, hacia adelante)."}, {"id": 48, "q": "La determinación de las fechas máximas en un programa o camino crítico según el método de los potenciales de Bernard Roy y que se escriben encima de su recuadro…", "opts": {"A": "se determinan de derecha a izquierda.", "B": "se determinan de izquierda a derecha.", "C": "se determinan iniciando por las actividades de valor más elevado.", "D": "se determinan iniciando por las actividades de menor valor."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Las fechas MÁXIMAS (más tardías) se calculan de DERECHA a IZQUIERDA (cálculo de vuelta, hacia atrás desde el final)."}, {"id": 49, "q": "El ser Director facultativo de un Proyecto supone asumir responsabilidades en los campos…", "opts": {"A": "técnico.", "B": "civil y penal.", "C": "en los dos anteriores.", "D": "sólo en el civil."}, "correct": "C", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "El Director facultativo asume responsabilidad técnica y también civil y penal: por eso 'en los dos anteriores'."}, {"id": 50, "q": "La evaluación de proyectos es una materia…", "opts": {"A": "Interdisciplinar.", "B": "Del departamento de fabricación.", "C": "Del departamento de comercialización.", "D": "Del departamento de organización de la producción."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "La evaluación de proyectos es INTERDISCIPLINAR: combina aspectos técnicos, económicos, comerciales, sociales y ambientales."}, {"id": 51, "q": "Una buena técnica de análisis en la evaluación de un proyecto …", "opts": {"A": "Solo tiene en cuenta las decisiones de tipo personal", "B": "Obtiene solamente su rentabilidad económica", "C": "Aporta la rentabilidad social", "D": "Todas las anteriores."}, "correct": "C", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Una buena evaluación no solo mide la rentabilidad económica, también aporta la rentabilidad SOCIAL del proyecto."}, {"id": 52, "q": "La primera etapa en la evaluación de un proyecto es:", "opts": {"A": "Estudio de prefactibilidad", "B": "Evaluación definitiva", "C": "Gran visión", "D": "Fase 0."}, "correct": "C", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "La primera etapa (la más superficial) de la evaluación es la GRAN VISIÓN, antes de la prefactibilidad y la evaluación definitiva."}, {"id": 53, "q": "Qué análisis es el aspecto más ambiguo y descuidado de la mercadotecnia …", "opts": {"A": "El de la comercialización.", "B": "El de la oferta", "C": "El de la demanda", "D": "El de los precios."}, "correct": "A", "tema": "Evaluación económica", "src": "banco", "exp": "El análisis de la COMERCIALIZACIÓN es el aspecto más ambiguo y descuidado del estudio de mercado, por su dificultad de cuantificar."}, {"id": 54, "q": "Los intermediarios en la comercialización …", "opts": {"A": "Adquieren el título de propiedad de la mercancía", "B": "Facilitan el control sobre el producto", "C": "Pueden reducir el costo de venta al comprar grandes cantidades", "D": "No venden a crédito."}, "correct": "C", "tema": "Evaluación económica", "src": "banco", "exp": "Los intermediarios pueden REDUCIR el coste de venta al comprar grandes cantidades (asumen funciones de distribución)."}, {"id": 55, "q": "Los “costos hundidos” son …", "opts": {"A": "Costos de oportunidad", "B": "Costos pasados", "C": "Costos por depreciación", "D": "Costos virtuales. 2"}, "correct": "B", "tema": "General", "src": "banco", "exp": "Los 'costos hundidos' son costos PASADOS, ya incurridos e irrecuperables: no deben influir en decisiones futuras."}, {"id": 56, "q": "Los costos de producción no incluyen …", "opts": {"A": "Mano de obra indirecta", "B": "Costo de venta", "C": "Costo de administración", "D": "Todas las respuestas son correctas."}, "correct": "A", "tema": "General", "src": "banco", "exp": "En la clasificación del temario, los costes de producción directos son materia prima y mano de obra directa; la mano de obra INDIRECTA se imputa aparte como coste indirecto/general."}, {"id": 57, "q": "El sueldo de los ingenieros es …", "opts": {"A": "Costos de mano de obra directa", "B": "Costos de producción", "C": "Costos financieros", "D": "Costos generales."}, "correct": "D", "tema": "General", "src": "banco", "exp": "El sueldo de los ingenieros se considera un COSTE GENERAL (no es mano de obra directa de producción)."}, {"id": 58, "q": "El activo diferido o intangible comprende bienes de la empresa como …", "opts": {"A": "Contratos de servicios", "B": "Costos por depreciación", "C": "Costos hundidos", "D": "Costos de inversión futura."}, "correct": "A", "tema": "General", "src": "banco", "exp": "El activo diferido o INTANGIBLE recoge bienes no materiales como los contratos de servicios, patentes o gastos de constitución."}, {"id": 59, "q": "El activo fijo comprende bienes de la empresa como:…", "opts": {"A": "Máquinas herramienta", "B": "Inversiones iniciales intangibles", "C": "Pasivos circulantes", "D": "Costos hundidos. 3"}, "correct": "A", "tema": "General", "src": "banco", "exp": "El activo FIJO son los bienes materiales duraderos, como las máquinas-herramienta."}, {"id": 60, "q": "Si una empresa sufre riesgos de no poder pagar sus deudas de corto plazo su tasa circulante será …", "opts": {"A": "Menor de 1", "B": "Entre 1 y 2", "C": "Entre 2 y 3", "D": "Superior a 3."}, "correct": "A", "tema": "General", "src": "banco", "exp": "Si hay riesgo de no pagar las deudas a corto plazo, la tasa circulante (activo circulante/pasivo circulante) es MENOR DE 1."}, {"id": 61, "q": "Para evaluar proyectos se considera aconsejable una tasa de circulación …", "opts": {"A": "Menor de 1", "B": "Entre 1 y 2", "C": "Entre 2 y 3", "D": "Superior a 3."}, "correct": "D", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Para evaluar proyectos se considera segura una tasa de circulación elevada, SUPERIOR A 3: indica gran holgura para cubrir las deudas a corto."}, {"id": 62, "q": "La decisión de llevar a la practica un determinado proyecto…", "opts": {"A": "es solo el trabajo del gerente de la empresa.", "B": "es susceptible solo de aplicación industrial típica.", "C": "corresponde a un grupos multidisciplinarios que cuentan con la mayor cantidad de información posible.", "D": "ninguna de las anteriores."}, "correct": "C", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Decidir llevar a la práctica un proyecto corresponde a GRUPOS MULTIDISCIPLINARES que reúnen la mayor información posible (no a una sola persona)."}, {"id": 63, "q": "La evaluación de un proyecto…", "opts": {"A": "no depende del criterio adoptado de acuerdo con el objetivo general del proyecto.", "B": "depende en gran medida del criterio adoptado de acuerdo con el objetivo general del proyecto.", "C": "tiene siempre un carácter subjetivo.", "D": "ninguna de las anteriores. 4"}, "correct": "B", "tema": "Normativa (CTE, incendios, seguridad)", "src": "banco", "exp": "La evaluación DEPENDE en gran medida del criterio adoptado según el objetivo general del proyecto (no es algo único ni puramente subjetivo)."}, {"id": 64, "q": "En el proceso de evaluación del proyecto se pueden considerar tres niveles de profundidad…", "opts": {"A": "Gran Visión, Prefactibilidad y Evaluación definitiva.", "B": "Prefase 1, 2 y fase de decisiones.", "C": "Anteproyecto, Diseño de Detalle, Estudio de Costes.", "D": "Ninguna de las anteriores."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Los tres niveles de profundidad de la evaluación son: Gran Visión, Prefactibilidad y Evaluación definitiva (de menos a más detalle)."}, {"id": 65, "q": "La evaluación del proyecto suelen seguirse los siguientes pasos o etapas…", "opts": {"A": "Estudio técnico simplificado de detalle y de ejecución", "B": "Verificar que existe un mercado potencial, demostrar que tecnológicamente es posible, y demostrar que es económicamente rentable", "C": "Estudio de fabricación y de rentabilidad.", "D": "Evaluación técnica de la idea y estudio de explotación final."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Los pasos clave son: verificar que existe MERCADO, demostrar que es técnicamente posible y demostrar que es económicamente rentable."}, {"id": 66, "q": "Son objetivos del estudio técnico …", "opts": {"A": "verificar la posibilidad técnica de fabricación del producto objeto del proyecto.", "B": "solamente relacionar coste con las funciones técnicas esenciales.", "C": "los indicados en A y B.", "D": "solamente calcular el árbol funcional del producto. 5"}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "El objetivo del estudio técnico es verificar la POSIBILIDAD TÉCNICA de fabricar el producto del proyecto."}, {"id": 67, "q": "Una evaluación simplificada de impacto ambiental debe contener…", "opts": {"A": "la redacción del proyecto técnico.", "B": "la declaración de impacto ambiental.", "C": "el estudio simplificado de impacto ambiental.", "D": "un resumen de la información sobre localización, alternativas, materias primas, inventario ambiental, etc."}, "correct": "D", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "La evaluación simplificada de impacto ambiental contiene un RESUMEN de localización, alternativas, materias primas, inventario ambiental, etc."}, {"id": 68, "q": "El estudio de seguridad y salud es obligatorio cuando…", "opts": {"A": "el proyecto supere los 100.000 euros.", "B": "la duración de la obra sea superior a los 20 días.", "C": "el volumen de mano de obra supere las 400 jornadas.", "D": "se trate de un túnel."}, "correct": "D", "tema": "Normativa (CTE, incendios, seguridad)", "src": "banco", "exp": "El estudio de seguridad y salud es obligatorio en obras especiales de riesgo, como los TÚNELES (entre los casos del RD 1627/1997)."}, {"id": 69, "q": "De conformidad con el articulado sobre Prevención de Riesgos Laborales, en la obra hay que tener un libro de incidencias…", "opts": {"A": "siempre.", "B": "en los casos previstos por la legislación.", "C": "a criterio de la empresa.", "D": "por acuerdo entre empresa y trabajadores."}, "correct": "A", "tema": "General", "src": "banco", "exp": "En la obra hay que tener SIEMPRE un libro de incidencias para el control de la seguridad y salud."}, {"id": 70, "q": "Los equipos redactores de Estudios de Impacto Ambiental, estarán formados por…", "opts": {"A": "dos personas con competencia en impacto ambiental y otras dos en proyectos técnicos.", "B": "al menos dos técnicos en medio ambiente.", "C": "al menos por dos personas con titulación universitaria.", "D": "más de dos personas con titulación universitaria en medio ambiente."}, "correct": "C", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "Los equipos redactores de Estudios de Impacto Ambiental deben formarse por AL MENOS DOS personas con titulación universitaria."}, {"id": 71, "q": "El documento de síntesis es obligatorio…", "opts": {"A": "en los estudios simplificados de impacto ambiental.", "B": "en los estudios de las evaluaciones ordinarias y simplificadas de impacto ambiental.", "C": "en las declaraciones de impacto ambiental.", "D": "en los estudios ordinarios de impacto ambiental."}, "correct": "B", "tema": "General", "src": "banco", "exp": "El documento de síntesis es obligatorio en las evaluaciones de impacto ambiental ORDINARIAS Y SIMPLIFICADAS."}, {"id": 72, "q": "La persona física distinta del contratista y del subcontratista, que realiza de forma personal y directa una actividad profesional, sin sujeción a un contrato de trabajo, y que asume contractualmente ante el promotor, el contratista o el subcontratista el compromiso de realizar determinadas partes o instalaciones de la obra, se denomina…", "opts": {"A": "contratista.", "B": "subcontratista.", "C": "trabajador autónomo.", "D": "ninguna de ellas."}, "correct": "C", "tema": "Organización de la empresa", "src": "banco", "exp": "Quien ejecuta parte de la obra de forma personal y directa, sin contrato de trabajo, es el TRABAJADOR AUTÓNOMO."}, {"id": 73, "q": "El Estudio Básico de Seguridad y Salud lo elaborará…", "opts": {"A": "el jefe de obra.", "B": "el técnico de la empresa contratada por el empresario.", "C": "el coordinador en materia de seguridad y salud durante la ejecución de la obra.", "D": "el técnico competente designado por el promotor."}, "correct": "D", "tema": "Normativa (CTE, incendios, seguridad)", "src": "banco", "exp": "El Estudio Básico de Seguridad y Salud lo elabora el TÉCNICO COMPETENTE designado por el promotor (en la fase de proyecto)."}, {"id": 74, "q": "El Plan de Seguridad lo elaborará…", "opts": {"A": "el proyectista.", "B": "la dirección facultativa.", "C": "el contratista.", "D": "el coordinador en materia de seguridad y salud durante la ejecución de la obra."}, "correct": "C", "tema": "Normativa (CTE, incendios, seguridad)", "src": "banco", "exp": "El Plan de Seguridad y Salud lo elabora el CONTRATISTA (que es quien ejecuta y debe organizar su prevención)."}, {"id": 75, "q": "En la redacción y ejecución de los proyectos técnicos y estudios de seguridad interviene el…", "opts": {"A": "promotor.", "B": "coordinador en materia de seguridad y de salud.", "C": "contratista.", "D": "subcontratista."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "En la redacción y ejecución interviene el COORDINADOR en materia de seguridad y salud, que vela por la prevención en ambas fases."}, {"id": 76, "q": "La evaluación ordinaria de impacto ambiental…", "opts": {"A": "es el procedimiento aplicable a las actividades que tienen, o pueden tener, gran incidencia en el medio ambiente.", "B": "es el procedimiento utilizado para realizar una declaración de impacto ambiental.", "C": "se redacta en todos los proyectos técnicos.", "D": "es parte del estudio de impacto ambiental."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "La evaluación ordinaria de impacto ambiental se aplica a actividades con GRAN incidencia ambiental (las de mayor impacto)."}, {"id": 77, "q": "El Real Decreto 1627/1997 establece:", "opts": {"A": "los medios de seguridad en la ejecución de proyectos.", "B": "las normas de seguridad en los trabajos de construcción.", "C": "las disposiciones mínimas de seguridad y salud, aplicables a las obras de construcción.", "D": "los estudios básicos de seguridad."}, "correct": "C", "tema": "Normativa (CTE, incendios, seguridad)", "src": "banco", "exp": "El RD 1627/1997 establece las disposiciones mínimas de seguridad y salud aplicables a las OBRAS DE CONSTRUCCIÓN."}, {"id": 78, "q": "El Plan de Seguridad estará basado en…", "opts": {"A": "el Proyecto Técnico de Seguridad.", "B": "el Estudio de Seguridad.", "C": "las directrices del coordinador en materia de seguridad y salud durante la ejecución de la obra.", "D": "el libro de incidencias."}, "correct": "B", "tema": "Normativa (CTE, incendios, seguridad)", "src": "banco", "exp": "El Plan de Seguridad se basa en el ESTUDIO de Seguridad (lo desarrolla y adapta a la forma real de ejecutar la obra)."}, {"id": 79, "q": "La norma legal por la que se determina el cuerpo básico de garantías y responsabilidades preciso para establecer un adecuado nivel de protección de la salud de los trabajadores frente a los riesgos derivados de las condiciones de trabajo, en el marco de una política coherente, coordinada y eficaz, recibe el nombre de…", "opts": {"A": "Real Decreto sobre Seguridad e Impacto ambiental.", "B": "Estudio de Seguridad e Impacto ambiental.", "C": "Ley de prevención de Riesgos Laborales.", "D": "Normas sobre Seguridad e Impacto ambiental."}, "correct": "C", "tema": "Normativa (CTE, incendios, seguridad)", "src": "banco", "exp": "La norma que fija las garantías para proteger la salud de los trabajadores es la LEY DE PREVENCIÓN DE RIESGOS LABORALES (Ley 31/1995)."}, {"id": 80, "q": "La declaración de impacto ambiental determinará a efectos ambientales…", "opts": {"A": "la conveniencia o no de ejecutar el proyecto.", "B": "las condiciones técnicas y ambientales para la ejecución del proyecto.", "C": "los impactos principales del proyecto.", "D": "la inclusión del proyecto en la Consejería de Medio Ambiente. SOLUCIONES: Estudios de Seguridad e Impacto Ambiental."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "La declaración de impacto ambiental determina la CONVENIENCIA O NO de ejecutar el proyecto a efectos ambientales."}, {"id": 81, "q": "En la industrialización de un producto diseñado, la personalización del artículo a bajo coste y el período de introducción en el mercado, son requisitos…", "opts": {"A": "fabriles.", "B": "comerciales.", "C": "sociales y medioambientales.", "D": "todos los mencionados."}, "correct": "B", "tema": "General", "src": "banco", "exp": "Personalizar el artículo a bajo coste y el plazo de introducción en el mercado son requisitos COMERCIALES (orientados a vender)."}, {"id": 82, "q": "Una fase de diseño que ignora el proceso de fabricación…", "opts": {"A": "puede acarrear fuertes inversiones en instalaciones productivas.", "B": "permite obtener el diseño idóneo.", "C": "ambas.", "D": "ninguna de ellas."}, "correct": "A", "tema": "General", "src": "banco", "exp": "Diseñar ignorando el proceso de fabricación puede obligar a FUERTES INVERSIONES en instalaciones para poder fabricar ese diseño."}, {"id": 83, "q": "El diagrama que contempla todas las subfases, su orden temporal y su duración es lo que constituye un…", "opts": {"A": "diagrama de fases.", "B": "diagrama de proceso.", "C": "diagrama del proyecto.", "D": "cualquiera de las anteriores."}, "correct": "B", "tema": "Diagramas de proceso", "src": "banco", "exp": "El diagrama que recoge todas las subfases, su orden temporal y su duración es el DIAGRAMA DE PROCESO."}, {"id": 84, "q": "En el proceso industrial de fabricación de un elemento…", "opts": {"A": "se analizan las partes globales del mismo.", "B": "se analizan las actividades específicas sin realizar un detalle exhaustivo.", "C": "se analizan con detalle las actividades específicas.", "D": "se analiza, con mayor o menor detalle, en base al presupuesto disponible."}, "correct": "C", "tema": "Documentos del proyecto", "src": "banco", "exp": "En el proceso industrial se analizan CON DETALLE las actividades específicas, para poder fabricar correctamente."}, {"id": 85, "q": "Qué actividad es la que presenta la mayor amplitud (duración) en un proyecto.", "opts": {"A": "Operación.", "B": "Fase.", "C": "Subfase.", "D": "Es independiente la amplitud del tipo de actividad."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "banco", "exp": "La OPERACIÓN es la actividad de mayor amplitud (duración); se descompone en fases y éstas en subfases."}, {"id": 86, "q": "Operaciones, fases y subfases son actividades de un…", "opts": {"A": "proceso.", "B": "procedimiento.", "C": "ambos.", "D": "ninguno de los dos."}, "correct": "A", "tema": "Fases y estructura del proyecto", "src": "banco", "exp": "Operaciones, fases y subfases son las actividades en que se descompone un PROCESO."}, {"id": 87, "q": "La actividad que tiene lugar cuando en el proceso se produce un cambio intencionado en las características físicas o químicas de un elemento, se denomina…", "opts": {"A": "operación.", "B": "transporte.", "C": "almacenamiento.", "D": "inspección."}, "correct": "A", "tema": "Normativa (CTE, incendios, seguridad)", "src": "banco", "exp": "Cuando se produce un cambio intencionado en las características físicas o químicas de un elemento, la actividad es una OPERACIÓN."}, {"id": 88, "q": "Las inspecciones durante un proceso industrial…", "opts": {"A": "se suelen intercalar entre otras actividades, para comprobar el elemento en cuestión en esa fase del trabajo.", "B": "se programan al final del proceso.", "C": "las dos anteriores.", "D": "no se realizan inspecciones."}, "correct": "C", "tema": "Diagramas de proceso", "src": "banco", "exp": "Las inspecciones se intercalan entre actividades y también pueden programarse al final: por eso 'las dos anteriores'."}, {"id": 89, "q": "La actividad simple a señalar en los diagramas de proceso y que consiste en el traslado intencionado de un objeto o producto de un lugar a otro recibe el nombre de…", "opts": {"A": "transporte, en cualquier caso.", "B": "transporte, si se trata de recorridos superiores a un metro.", "C": "desplazamiento si se trata de paso del material en fabricación continua de un puesto de trabajo al siguiente.", "D": "traslado de material en los casos de trabajo en línea."}, "correct": "B", "tema": "Diagramas de proceso", "src": "banco", "exp": "El TRANSPORTE es el traslado intencionado de un objeto en recorridos superiores a UN METRO (por debajo no se considera transporte)."}, {"id": 90, "q": "En un diagrama de proceso, la espera imprevista, al no pertenecer al proceso…", "opts": {"A": "no origina coste de mano de obra.", "B": "origina una interrupción del proceso.", "C": "no retrasa la producción.", "D": "todas las anteriores."}, "correct": "B", "tema": "Diagramas de proceso", "src": "banco", "exp": "La espera imprevista no pertenece al proceso y provoca una INTERRUPCIÓN del mismo (sí genera coste y retraso)."}, {"id": 91, "q": "La actividad simple que consiste en la estancia controlada de un elemento, material o producto hasta ser incluido en el proceso de trabajo correspondiente, se denomina…", "opts": {"A": "inmovilidad.", "B": "espera.", "C": "almacenamiento.", "D": "cualquiera de las anteriores."}, "correct": "C", "tema": "General", "src": "banco", "exp": "La estancia controlada de un material hasta incorporarse al proceso es el ALMACENAMIENTO."}, {"id": 92, "q": "Si en un diagrama de proceso aparece el símbolo                 indica una actividad simple de…", "opts": {"A": "operación.", "B": "inspección.", "C": "transporte.", "D": "espera."}, "correct": "A", "tema": "Diagramas de proceso", "src": "banco", "exp": "El símbolo de círculo representa una OPERACIÓN en los diagramas de proceso."}, {"id": 93, "q": "Un diagrama de proceso que refleja todo tipo de actividades del proceso de trabajo pormenorizadas de manera conveniente, recibe el nombre de…", "opts": {"A": "diagrama de fabricación.", "B": "diagrama analítico.", "C": "diagrama sinóptico.", "D": "diagrama gráfico."}, "correct": "B", "tema": "Diagramas de proceso", "src": "banco", "exp": "El diagrama que refleja TODAS las actividades pormenorizadas es el DIAGRAMA ANALÍTICO (cursograma analítico)."}, {"id": 94, "q": "Un diagrama de proceso que representa las operaciones e inspecciones de forma abreviada para apreciar con rapidez las partes principales del proceso, recibe el nombre de…", "opts": {"A": "diagrama de fabricación.", "B": "diagrama analítico.", "C": "diagrama sinóptico.", "D": "diagrama gráfico."}, "correct": "C", "tema": "Diagramas de proceso", "src": "banco", "exp": "El que solo representa operaciones e inspecciones para ver rápido las partes principales es el DIAGRAMA SINÓPTICO."}, {"id": 95, "q": "Según las tendencias actuales del diseño…", "opts": {"A": "el proceso de diseño debe estar completo al comenzar la fase de industrialización.", "B": "la fase de diseño es de incumbencia exclusiva del Departamento de Diseño.", "C": "el diseño del producto se basa en la ingeniería concurrente.", "D": "todas ellas."}, "correct": "C", "tema": "Organización de la empresa", "src": "banco", "exp": "Las tendencias actuales basan el diseño del producto en la INGENIERÍA CONCURRENTE (diseño y fabricación a la vez)."}, {"id": 96, "q": "El diseño debe realizarse…", "opts": {"A": "de manera secuencial (Especificaciones --> Diseño --> Fabricación).", "B": "con libertad en el diseño inicial y posteriormente acomodar el producto al proceso que se determine.", "C": "estableciendo el diseño y el proceso simultáneamente Diseño y Fabricación.", "D": "cualquiera de las anteriores."}, "correct": "C", "tema": "Modelos y diseño", "src": "banco", "exp": "El diseño debe hacerse estableciendo el diseño y el proceso SIMULTÁNEAMENTE (ingeniería concurrente), no de forma secuencial."}, {"id": 97, "q": "Si se prevé un volumen de fabricación elevado (artículo de gran consumo), éste debe diseñarse…", "opts": {"A": "igual que si fuera para una producción limitada.", "B": "facilitando las operaciones de montaje masivo.", "C": "ambas.", "D": "ninguna de ellas."}, "correct": "B", "tema": "General", "src": "banco", "exp": "Si el volumen de fabricación es elevado, el producto debe diseñarse FACILITANDO el montaje masivo (Diseño para Fabricación y Montaje)."}, {"id": 98, "q": "Cuando en la fase de diseño intervienen también los ingenieros de fabricación, formando grupos que utilizan metodologías y herramientas de análisis para evaluar los diseños en términos de fabricabilidad del producto, se está aplicando los principios de…", "opts": {"A": "sinergia.", "B": "ingeniería concurrente.", "C": "grupos interdisciplinares.", "D": "cualquiera de los anteriores."}, "correct": "B", "tema": "General", "src": "banco", "exp": "Que los ingenieros de fabricación participen en el diseño evaluando la fabricabilidad es aplicar la INGENIERÍA CONCURRENTE."}, {"id": 99, "q": "Un proceso industrial está constituido…", "opts": {"A": "por la sucesión de actividades que tienen como finalidad la obtención de un determinado producto.", "B": "por las máquinas que permiten su realización.", "C": "por los operarios que lo van a llevar a cabo.", "D": "por todas ellas."}, "correct": "A", "tema": "Evaluación económica", "src": "banco", "exp": "Un proceso industrial es la SUCESIÓN DE ACTIVIDADES cuya finalidad es obtener un producto (las máquinas y operarios son medios)."}, {"id": 100, "q": "Qué actividad no forma parte de las cinco actividades simples que constituyen un diagrama de proceso.", "opts": {"A": "Transporte.", "B": "Almacenamiento.", "C": "Inspección.", "D": "Fabricación."}, "correct": "D", "tema": "Diagramas de proceso", "src": "banco", "exp": "Las cinco actividades simples son operación, transporte, inspección, espera y almacenamiento. 'Fabricación' NO es una de ellas."}, {"id": 101, "q": "Los cambios de forma, de propiedades mecánicas, de composición química o superficial, los montajes solidarios y no solidarios, dentro de un diagrama de proceso, son considerados una actividad simple denominada…", "opts": {"A": "operación.", "B": "transporte.", "C": "almacenamiento.", "D": "inspección."}, "correct": "A", "tema": "Diagramas de proceso", "src": "banco", "exp": "Cambios de forma, propiedades o montajes son una OPERACIÓN (modifican intencionadamente el elemento)."}, {"id": 102, "q": "La actividad que consiste en el examen programado que se realiza sobre un elemento o producto para verificar algunas de sus características: forma, dimensiones, composición, funcionamiento, aspecto, etc., se denomina…", "opts": {"A": "operación.", "B": "transporte.", "C": "almacenamiento.", "D": "inspección."}, "correct": "D", "tema": "Normativa (CTE, incendios, seguridad)", "src": "banco", "exp": "El examen programado para verificar características (forma, dimensiones, funcionamiento…) es una INSPECCIÓN."}, {"id": 103, "q": "El almacenamiento como actividad simple de un diagrama de proceso…", "opts": {"A": "retrasa la producción.", "B": "produce costo de MOD.", "C": "supone riesgo de obsolescencia y/o deterioro.", "D": "todas las anteriores."}, "correct": "C", "tema": "Diagramas de proceso", "src": "banco", "exp": "El almacenamiento supone riesgo de OBSOLESCENCIA y/o DETERIORO del material almacenado."}, {"id": 104, "q": "Un Diagrama del proceso de trabajo…", "opts": {"A": "se realiza considerando el trabajo de los operarios.", "B": "se realiza considerando el trabajo de las máquinas.", "C": "puede realizarse por cualquiera de las anteriores.", "D": "hay que imperativamente realizarlo por ambas."}, "correct": "C", "tema": "General", "src": "banco", "exp": "El diagrama del proceso puede hacerse considerando el trabajo de los operarios o el de las máquinas: CUALQUIERA de ambos."}, {"id": 105, "q": "En la parte central del formato de un diagrama de proceso se confecciona el diagrama propiamente dicho. Indicar el tipo de impreso representado.", "opts": {"A": "en blanco.", "B": "impresa.", "C": "ambos.", "D": "ninguno de ellos."}, "correct": "B", "tema": "Diagramas de proceso", "src": "banco", "exp": "La parte central del formato del diagrama va IMPRESA (con la malla de símbolos preimpresa para rellenar)."}, {"id": 106, "q": "La principal clave del éxito de un diseño es…", "opts": {"A": "la consideración desde el principio de todas las restricciones y objetivos.", "B": "conseguir el precio más económico posible.", "C": "ambas.", "D": "ninguna de las anteriores."}, "correct": "A", "tema": "General", "src": "banco", "exp": "La principal clave del éxito de un diseño es considerar DESDE EL PRINCIPIO todas las restricciones y objetivos."}, {"id": 107, "q": "El trabajo en paralelo de Diseño y Fabricación durante el desarrollo de un artículo recibe el nombre de…", "opts": {"A": "sinergia.", "B": "ingeniería concurrente.", "C": "grupo interdisciplinar.", "D": "cualquiera de los anteriores."}, "correct": "B", "tema": "General", "src": "banco", "exp": "El trabajo en paralelo de Diseño y Fabricación se llama INGENIERÍA CONCURRENTE."}, {"id": 108, "q": "Un Diagrama del proceso de trabajo es…", "opts": {"A": "la representación gráfica y secuencial de un proceso mediante símbolos normalizados.", "B": "un lugar donde se anotan los tiempos concedidos.", "C": "las dos anteriores.", "D": "ninguna de ellas."}, "correct": "C", "tema": "Diagramas de proceso", "src": "banco", "exp": "El diagrama del proceso es a la vez la representación gráfica con símbolos y el soporte donde se anotan los tiempos: 'las dos anteriores'."}, {"id": 109, "q": "En una distribución en planta de tipo funcional", "opts": {"A": "La mano de obra tiene menor especialización que en una distribución en línea", "B": "El tiempo unitario es mayor que en una distribución en línea", "C": "La estrategia de incentivo es por logro conjunto", "D": "La estrategia de incentivo es de compleja aplicación"}, "correct": "B", "tema": "General", "src": "banco", "exp": "En la distribución funcional (por proceso) el TIEMPO UNITARIO es MAYOR que en línea, porque el material recorre más y espera más."}, {"id": 110, "q": "Una adecuada distribución en planta del proceso:", "opts": {"A": "solamente es necesario en procesos complejos", "B": "consigue una adecuada utilización de los recursos", "C": "siempre aumenta el coste final del producto", "D": "en ningún caso es necesaria en un proceso simple"}, "correct": "B", "tema": "General", "src": "banco", "exp": "Una buena distribución en planta consigue una adecuada UTILIZACIÓN DE LOS RECURSOS (siempre es útil, también en procesos simples)."}, {"id": 111, "q": "Como primera aproximación, ¿qué herramienta, como punto de partida, emplearía para realizar una mejora de métodos de trabajo?", "opts": {"A": "El diagrama analítico del proceso a mejorar", "B": "El diagrama de explotación del proceso a mejorar", "C": "El diagrama de actividades simultaneas de producción continua a mejorar", "D": "Ninguno de los anterioresle"}, "correct": "A", "tema": "Diagramas de proceso", "src": "banco", "exp": "Para mejorar métodos de trabajo se parte del DIAGRAMA ANALÍTICO del proceso actual, que registra todas las actividades a estudiar."}, {"id": 112, "q": "En una distribución en planta de tipo in situ", "opts": {"A": "El material no concurre en el puesto", "B": "El incentivo es por logro conjunto", "C": "El material concurre en el puesto", "D": "La cualificación de toda la MOD es mínima"}, "correct": "C", "tema": "General", "src": "banco", "exp": "En la distribución 'in situ' el producto está fijo y EL MATERIAL CONCURRE EN EL PUESTO (van a él los recursos)."}, {"id": 113, "q": "La mejora de métodos de trabajo consiste en…", "opts": {"A": "Registrar el método actual, estudiar el método ac-tual con actitud crítica y reflexiva, proponer un nuevo método e implantar el nuevo método si procede", "B": "Analizar el propósito, lugar, secuencia, puesto de trabajo y medios de cada actividad", "C": "Eliminar, combinar, reordenar y simplificar las activi-dades", "D": "Confeccionar el diagrama analítico del proceso actual indicando las características de cada actividad"}, "correct": "A", "tema": "Normativa (CTE, incendios, seguridad)", "src": "banco", "exp": "La mejora de métodos consiste en: registrar el método actual, estudiarlo con actitud crítica, proponer uno nuevo e implantarlo si procede."}, {"id": 114, "q": "Una línea de montaje de componentes de automóvil responde a una distribución en planta:", "opts": {"A": "Por producto", "B": "Por proceso", "C": "Localización fija o “in situ”", "D": "Ninguna de las anteriores"}, "correct": "A", "tema": "General", "src": "banco", "exp": "Una línea de montaje de automóviles es una distribución POR PRODUCTO (el producto avanza por puestos en secuencia)."}, {"id": 115, "q": "En una empresa industrial, el departamento que se encarga de elaborar los presupuestos de los proyectos es", "opts": {"A": "Métodos y tiempos.", "B": "Estudios y Proyectos.", "C": "Contabilidad y costes.", "D": "Compras."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "En las industrias, el área de \"Estudios y Proyectos\" es la responsable del diseño preliminar, desarrollo técnico y valoración económica (presupuesto) antes de aprobar y licitar una obra."}, {"id": 116, "q": "La actividad de proyectos se desarrolla…", "opts": {"A": "fundamentalmente en la dirección técnica.", "B": "solamente en la Dirección comercial.", "C": "como responsabilidad única de la dirección de la empresa.", "D": "fundamentalmente en los departamentos de gestión económica y administración de la empresa."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "La ingeniería de proyectos es una actividad técnica de diseño y cálculo, por lo que pertenece directamente al área de competencia de la Dirección Técnica de la empresa."}, {"id": 117, "q": "Al considerar en una planificación el factor coste...", "opts": {"A": "La ejecución normal se corresponde con la utilización óptima de los recursos y, por ello, es la de coste mínimo.", "B": "En la ejecución acelerada también se repara en el coste a fin de reducir al mínimo la duración de la actividad.", "C": "En una planificación nunca debe considerarse el factor coste.", "D": "Son correctas las respuestas A y B."}, "correct": "A", "tema": "General", "src": "Examen 2024", "exp": "En la planificación de proyectos (intercambio tiempo-coste), la \"duración normal\" de una actividad es aquella en la que los recursos se usan a ritmo óptimo, resultando en el mínimo coste directo (sin sobrecostes por horas extras o envíos urgentes)."}, {"id": 118, "q": "La dirección facultativa…", "opts": {"A": "Representa al promotor en la obra.", "B": "Representa al contratista en la obra.", "C": "Nombra al coordinador en materia de seguridad.", "D": "Ninguna es correcta."}, "correct": "A", "tema": "Organización de la empresa", "src": "Examen 2024", "exp": "La Dirección Facultativa (formada por el director de obra y el director de ejecución de obra) es contratada por el dueño/promotor para supervisar que el contratista ejecute la obra según el proyecto."}, {"id": 119, "q": "El Código Técnico de la Edificación (CTE):", "opts": {"A": "Se aprobó mediante un Real Decreto.", "B": "Se aprobó mediante una Ley.", "C": "No es de obligado cumplimiento, es un manual de buenas prácticas en la edificación.", "D": "Son correctas las respuestas A y C."}, "correct": "A", "tema": "Normativa (CTE, incendios, seguridad)", "src": "Examen 2024", "exp": "El CTE es el marco normativo de edificación en España y fue aprobado mediante el **Real Decreto 314/2006**. Es una norma de obligado cumplimiento (por lo que las opciones C y D son falsas)."}, {"id": 120, "q": "Un precio básico es:", "opts": {"A": "La parte de una obra civil que se mide y valora de forma independiente, que se valora en función de una unidad de medida.", "B": "La medición de cada unidad de obra del proyecto.", "C": "Equivalente a una unidad de obra.", "D": "El correspondiente a un bien, alquiler o servicio tangible, valorable y con un precio en el mercado."}, "correct": "D", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "Los precios básicos son las tarifas unitarias de los recursos elementales de mercado (por ejemplo: precio/hora de un oficial, precio/metro de cable, precio/día de alquiler de una hormigonera)."}, {"id": 121, "q": "Los métodos de proyección en evaluación de proyectos:", "opts": {"A": "Se utilizan en el estudio de mercado para el análisis de la demanda.", "B": "Se utilizan en el estudio de mercado para el análisis de la comercialización.", "C": "Se utilizan en el estudio económico para hallar el punto muerto de la inversión.", "D": "Las respuestas A y B son ciertas."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "Los métodos de proyección (regresiones, series temporales) se aplican al inicio de un proyecto para estimar cómo evolucionará la demanda futura del mercado."}, {"id": 122, "q": "El proceso de montaje de una subestación para el abastecimiento eléctrico de una urbanización es:", "opts": {"A": "Un proceso continuo.", "B": "Un proceso de montaje en serie.", "C": "Un proceso de montaje in situ.", "D": "Un proceso desarrollado en línea de montaje."}, "correct": "C", "tema": "General", "src": "Examen 2024", "exp": "Una subestación eléctrica se ensambla e instala directamente en su emplazamiento definitivo (no en una fábrica en serie), por lo que es un proceso \"in situ\"."}, {"id": 123, "q": "Cuando se realiza el diagrama del proceso de un transporte.", "opts": {"A": "Nunca se incluye en un diagrama de proceso.", "B": "Se refleja en un diagrama analítico.", "C": "Se refleja en un diagrama sinóptico.", "D": "Se puede reflejar en diagramas analíticos y sinópticos."}, "correct": "B", "tema": "Diagramas de proceso", "src": "Examen 2024", "exp": "Los transportes (símbolo ▷) y las demoras solo se representan en el **diagrama analítico** (cursograma). El diagrama sinóptico solo incluye operaciones (⚪) e inspecciones (⬜)."}, {"id": 124, "q": "La definición de un proyecto, usos del producto, el estado de la técnica, y las fuentes de información, dentro de un proyecto técnico, son pasos de:", "opts": {"A": "Estudio preliminar.", "B": "Orden de magnitud.", "C": "Anteproyecto.", "D": "Proyecto detallado"}, "correct": "A", "tema": "Propiedad industrial y patentes", "src": "Examen 2024", "exp": "Es la primera fase del ciclo de vida del diseño, donde se define conceptualmente el problema y se investiga si es viable antes de realizar anteproyectos o proyectos detallados."}, {"id": 125, "q": "La decisión de compartir un recurso entre dos procesos:", "opts": {"A": "Es positiva siempre que las economías brutas de los dos procesos mejoren con independencia de la economía neta.", "B": "Es negativa puesto que siempre va a introducir esperas en ambos procesos.", "C": "Es positiva siempre y cuando la suma de las economías netas de los procesos sea positiva.", "D": "Es negativa independiente del valor de la amortización del recurso presente en ambos procesos."}, "correct": "C", "tema": "Evaluación económica", "src": "Examen 2024", "exp": "Compartir maquinaria o personal se justifica económicamente si el beneficio neto conjunto (ahorro en inversión menos pérdidas por esperas y logística) resulta positivo para la empresa."}, {"id": 126, "q": "El proyecto técnico o Diseño detallado es una fase…", "opts": {"A": "Creativa.", "B": "De construcción.", "C": "De explotación.", "D": "Todas las anteriores son correctas."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "El ciclo de vida de un proyecto se divide en: fase creativa (estudios, diseño detallado), fase de construcción (ejecución física en obra) y fase de explotación. Diseñar sobre el papel es una actividad creativa de ingeniería."}, {"id": 127, "q": "Los modelos icónicos son:", "opts": {"A": "Representaciones visuales.", "B": "Modelos matemáticos.", "C": "Abstracciones abreviadas de partes relevantes.", "D": "Métodos de análisis de comportamiento, real o virtual."}, "correct": "A", "tema": "Evaluación económica", "src": "Examen 2024", "exp": "Los modelos icónicos representan físicamente o visualmente el objeto real (por ejemplo: una maqueta 3D, un render o una fotografía a escala)."}, {"id": 128, "q": "La fase de recepción es una fase…", "opts": {"A": "Creativa.", "B": "De explotación.", "C": "De construcción.", "D": "De validación."}, "correct": "C", "tema": "General", "src": "Examen 2024", "exp": "La \"recepción de obra\" es el hito final de la **fase de construcción**, en el cual el promotor inspecciona la obra terminada, firma el acta de recepción y toma posesión de ella para empezar la explotación."}, {"id": 129, "q": "Son fases del proyecto técnico.", "opts": {"A": "Las Creativas y de construcción.", "B": "Las de construcción, Análisis, y Creativas.", "C": "Las Creativas, de Realización, y Análisis.", "D": "Todas las anteriores son correctas."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "De acuerdo con la metodología clásica, el ciclo general abarca las fases creativas (ingeniería) y las de construcción/realización (obra)."}, {"id": 130, "q": "El pliego de condiciones de un proyecto de una construcción industrial…", "opts": {"A": "Es independiente del tipo de promotor: público o privado.", "B": "Comprende las cláusulas administrativas y las prescripciones técnicas particulares del proyecto.", "C": "En el orden de prioridad de los documentos ocupa el último lugar.", "D": "Todas las respuestas anteriores son correctas."}, "correct": "A", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "El pliego de condiciones contiene las especificaciones técnicas de los materiales y de la ejecución de la obra. Estas reglas técnicas son las mismas sea el dueño de la obra el Estado o un particular."}, {"id": 131, "q": "El grafo supera al diagrama de Gantt.", "opts": {"A": "Porque considera los tiempos de una forma más precisa.", "B": "Porque proporciona información sobre la interdependencia de las distintas actividades.", "C": "Porque oculta detalles poco importantes como la criticidad de las tareas.", "D": "Porque su aspecto gráfico es más claro y visual."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "Gantt es ideal para ver tiempos en un calendario, pero falla al mostrar dependencias. Los diagramas de red (grafos PERT o ROY) muestran de forma explícita las relaciones lógicas y precedencias entre tareas."}, {"id": 132, "q": "Un anteproyecto…", "opts": {"A": "Es una fase de explotación que en ocasiones se denomina proyecto básico, y que se usa como documento de gestión.", "B": "Es una fase creativa que en proyectos de productos no se utiliza para petición de ayudas económicas.", "C": "Es una fase creativa que en ocasiones se denomina proyecto básico, y que se usa como documento de gestión.", "D": "Es una fase de explotación que en proyectos de productos no se utiliza para petición de ayudas económicas."}, "correct": "C", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "El anteproyecto es la última etapa de la fase creativa previa al proyecto detallado de ejecución. Define la solución general y sirve para solicitar licencias administrativas (por eso actúa como documento de gestión)."}, {"id": 133, "q": "Las características de los modelos simbólicos son…", "opts": {"A": "Economía de esfuerzo.", "B": "Comprobar los resultados.", "C": "Se apoyan en axiomas y leyes.", "D": "Todas las anteriores."}, "correct": "D", "tema": "Normativa (CTE, incendios, seguridad)", "src": "Examen 2024", "exp": "Los modelos matemáticos (simbólicos) permiten simular escenarios sin gastar en prototipos físicos (economía de esfuerzo), comprobar resultados matemáticos y se basan en fórmulas/leyes de la física."}, {"id": 134, "q": "Los modelos analógicos permiten…", "opts": {"A": "Intercambiar variables y parámetros.", "B": "Solamente la determinación de dimensiones.", "C": "Métodos gráficos para el cálculo.", "D": "Todas las anteriores son ciertas."}, "correct": "A", "tema": "General", "src": "Examen 2024", "exp": "Un modelo analógico utiliza un sistema físico conocido para representar a otro diferente (por ejemplo, modelar el flujo de agua en tuberías usando corriente eléctrica en resistencias, intercambiando variables de caudal/presión por intensidad/voltaje)."}, {"id": 135, "q": "De las siguientes características, ¿cuáles se identifican con un proyecto?", "opts": {"A": "Icónico.", "B": "Simple.", "C": "Multidisciplinar.", "D": "Multidisciplinar, complejo e icónico."}, "correct": "C", "tema": "Normativa (CTE, incendios, seguridad)", "src": "Examen 2024", "exp": "Un proyecto técnico siempre es complejo y requiere la colaboración de diferentes especialidades de ingeniería (estructuras, electricidad, medio ambiente, economía, etc.)."}, {"id": 136, "q": "La fase denominada proyecto o diseño detallado tiene por objetivo…", "opts": {"A": "Detallar los resultados en la fase de explotación del proyecto.", "B": "Desarrollar los cuatro documentos que forman el proyecto.", "C": "Desarrollar la fase de explotación del proyecto.", "D": "Desarrollar los documentos precisos para la definición constructiva del producto y su valoración económica."}, "correct": "D", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "En esta etapa se redactan los planos detallados, pliegos, mediciones y presupuestos necesarios para poder fabricar o construir directamente el proyecto."}, {"id": 137, "q": "El formato de menor tamaño a ser utilizado en un proyecto es…", "opts": {"A": "US-Letter (215.9 x 279.4mm)", "B": "UNE- A5", "C": "UNE- A4", "D": "UNE- A3"}, "correct": "C", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "Las normas de dibujo técnico para proyectos fijan el tamaño DIN A4 ($210 \\times 297 \\text{ mm}$) como el formato mínimo aceptado para la documentación escrita y planos oficiales."}, {"id": 138, "q": "El Estudio de Seguridad y Salud de un proyecto.", "opts": {"A": "Es uno de los cinco documentos del proyecto.", "B": "Es un anejo de la memoria.", "C": "Es un apartado de la memoria.", "D": "Forma parte del pliego de condiciones."}, "correct": "B", "tema": "Normativa (CTE, incendios, seguridad)", "src": "Examen 2024", "exp": "Según la estructura normalizada UNE 157001 y la ley española de prevención en construcción, el Estudio (o Estudio Básico) de Seguridad y Salud se incluye obligatoriamente como un **Anejo a la Memoria**."}, {"id": 139, "q": "La memoria es un documento que …", "opts": {"A": "Presenta las mediciones detalladas del proyecto.", "B": "Solamente justifica la necesidad del proyecto.", "C": "Describe de forma muy genérica el proyecto.", "D": "Enuncia el problema y justifica la necesidad del proyecto."}, "correct": "D", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "El Documento Nº1 (Memoria) describe la justificación social o industrial de la obra y expone el problema a resolver y la solución elegida."}, {"id": 140, "q": "Los precios básicos lo constituyen.", "opts": {"A": "Transporte y mano de obra.", "B": "Gastos de personal y de mantenimiento.", "C": "La mano de obra, maquinaria y materiales.", "D": "Ninguna de las anteriores es correcta."}, "correct": "C", "tema": "Diagramas de proceso", "src": "Examen 2024", "exp": "Son los tres recursos elementales que determinan el coste directo de cualquier unidad de obra."}, {"id": 141, "q": "El apartado de mediciones de un proyecto tiene como objeto…", "opts": {"A": "Medir solamente algunas de las unidades de obra del proyecto.", "B": "Permitir conocer el número de unidades que se deben ejecutar en cada unidad de obra.", "C": "No permitir la descomposición de las unidades de obra a ejecutar.", "D": "Todas las anteriores son ciertas."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "La medición cuantifica con precisión cuántas unidades de cada partida (ej. metros de cable, unidades de BIEs, etc.) se van a necesitar en total."}, {"id": 142, "q": "El importe de ejecución material incluye…", "opts": {"A": "El coste total del proyecto.", "B": "El coste total menos el IVA.", "C": "El coste total sin incluir los gastos generales, ni el beneficio industrial, ni tampoco el IVA.", "D": "Ninguna de las anteriores."}, "correct": "C", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "El PEM representa el coste neto en obra de los materiales, maquinaria y mano de obra. Los costes comerciales del contratista (GG y BI) y los impuestos (IVA) se añaden después."}, {"id": 143, "q": "El total presupuesto de ejecución por contrata por contrata…", "opts": {"A": "Únicamente establece el importe de ejecución material del proyecto.", "B": "Sirve como referencia para la adjudicación del proyecto.", "C": "Es el que utiliza el contratista para ejecutar la obra.", "D": "Es el que utiliza la dirección facultativa para asignar el proyecto a los autónomos."}, "correct": "B", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "Es el presupuesto oficial límite sin IVA que publica la administración o el promotor para que las empresas constructoras hagan sus ofertas y se adjudique la obra."}, {"id": 144, "q": "El montaje de un mecanismo podemos representarlo en un diagrama de proceso:", "opts": {"A": "Tiempos-Actividades con la parte central en blanco.", "B": "Analítico con la parte central impresa.", "C": "Sinóptico con la parte central impresa.", "D": "Estructurado con la parte central en blanco."}, "correct": "C", "tema": "Diagramas de proceso", "src": "Examen 2024", "exp": "Para ensamblajes de componentes (mecanismos), el diagrama idóneo es el **sinóptico** (muestra de forma muy visual y ramificada cómo se van uniendo las piezas). Se suele usar formato central impreso para simplificar el dibujo de los símbolos."}, {"id": 145, "q": "Cual de las siguientes opciones no es una ventaja que aporta una buena distribución en planta:", "opts": {"A": "Reducir el trabajo administrativo.", "B": "Reduce los tiempos de descanso de la mano de obra.", "C": "Incrementa la capacidad de producción.", "D": "Aumenta la moral de los trabajadores."}, "correct": "B", "tema": "General", "src": "Examen 2024", "exp": "Una buena distribución reduce distancias, mejora seguridad y aumenta producción. Sin embargo, no reduce los tiempos de descanso de los trabajadores, los cuales están regulados por ley y fisiología humana."}, {"id": 146, "q": "El Contratista…", "opts": {"A": "Contrata a los subcontratistas.", "B": "Realiza el plan de seguridad.", "C": "Contrata con el promotor la ejecución del proyecto.", "D": "Todas las anteriores."}, "correct": "D", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "El contratista general firma la ejecución de la obra con el promotor, redacta el Plan de Seguridad y Salud adaptado a sus equipos, y subcontrata partidas específicas a especialistas."}, {"id": 147, "q": "Según el REAL DECRETO 1627/1997, de 24 de octubre, por el que se establecen disposiciones mínimas de seguridad y salud en las obras de construcción, es necesaria la figura de Coordinador en materia de seguridad y salud:", "opts": {"A": "En el caso de que existan varios proyectistas durante la ejecución de la obra.", "B": "En caso de que existan varias empresas durante la ejecución de la obra.", "C": "En todos los casos.", "D": "Cuando así lo decida la dirección facultativa."}, "correct": "B", "tema": "Normativa (CTE, incendios, seguridad)", "src": "Examen 2024", "exp": "La designation de un Coordinador de Seguridad es **obligatoria** por ley desde el momento en que intervengan dos o más empresas, o una empresa y trabajadores autónomos, en la obra."}, {"id": 148, "q": "La evaluación de impacto ambiental.", "opts": {"A": "Es el proceso a través del cual se analizan los efectos significativos que tienen o pueden tener los proyectos, antes de su autorización sobre el medio ambiente.", "B": "No tiene en cuenta el efecto que el proyecto pueda tener sobre el patrimonio cultural.", "C": "Puede ser simplificada u ordinaria.", "D": "Son correcta A y C."}, "correct": "D", "tema": "Planificación y red PERT/CPM", "src": "Examen 2024", "exp": "Es un procedimiento administrativo para analizar los efectos ecológicos de un proyecto antes de autorizarlo. La normativa contempla dos niveles de tramitación: ordinaria (proyectos grandes) y simplificada."}, {"id": 149, "q": "El plan de seguridad y salud en el trabajo.", "opts": {"A": "Lo redacta el coordinador de seguridad y saludo durante la tase creativa.", "B": "Lo redacta el coordinador de seguridad y salud durante la fase constructiva.", "C": "Lo redacta el contratista.", "D": "Lo redacta el promotor."}, "correct": "C", "tema": "Normativa (CTE, incendios, seguridad)", "src": "Examen 2024", "exp": "Cada contratista que ejecuta la obra debe redactar su propio Plan de Seguridad, adaptando el Estudio de Seguridad del proyecto a sus medios auxiliares y métodos reales de trabajo."}, {"id": 150, "q": "La ingeniería simultánea o concurrente…", "opts": {"A": "Contempla que en la fase de diseño intervengan los ingenieros de fabricación.", "B": "Se sirve de metodologías y herramientas de análisis para evaluar los diseños en términos de su fabricabilidad.", "C": "Busca únicamente la mejor solución desde el punto de vista técnico.", "D": "Son correctas las respuestas A y la B."}, "correct": "D", "tema": "General", "src": "Examen 2024", "exp": "Consiste en integrar en el diseño de un producto a los ingenieros de fabricación desde las primeras etapas (A), evaluando la factibilidad y coste de producción mediante herramientas de análisis (B)."}, {"id": 151, "q": "¿Qué actividades simples no generan coste financiero?", "opts": {"A": "Transporte, Operación e Inspección.", "B": "Inspección, embalaje y operación.", "C": "Solamente Operación e inspección.", "D": "Espera prevista, espera imprevista y almacenamiento Es una actividad que no se representa en los diagramas sinópticos."}, "correct": "A", "tema": "Diagramas de proceso", "src": "Examen 2024", "exp": "Las actividades que aportan valor (operación, inspección) o que representan flujo de materiales activo (transporte) no se consideran fuentes de \"coste financiero de inmovilizado\". Sin embargo, las esperas y los almacenamientos prolongados sí acumulan coste de oportunidad y cargas financieras por capital parado."}, {"id": 152, "q": "¿Cuál de las siguientes actividades de un proceso retrasa la producción y genera coste financiero y coste para la mano de obra directa?", "opts": {"A": "Operación.", "B": "Espera imprevista.", "C": "Almacenamiento.", "D": "Espera prevista."}, "correct": "B", "tema": "Evaluación económica", "src": "Examen 2024", "exp": "Una espera imprevista (por ejemplo, avería de una máquina) para el proceso (coste financiero de inventario parado) y obliga a seguir pagando a los operarios directos que están ociosos esperando a que se resuelva (coste de MOD)."}, {"id": 153, "q": "El estudio de mejora de métodos de trabajo.", "opts": {"A": "Puede no generar modificaciones.", "B": "Es un estudio preliminar y aproximativo.", "C": "Utiliza solo diagramas analíticos.", "D": "Utiliza solo diagramas sinópticos."}, "correct": "A", "tema": "Fases y estructura del proyecto", "src": "Examen 2024", "exp": "Si tras analizar el proceso se concluye que el método actual ya es óptimo y eficiente, el estudio finalizará dictaminando que no es necesario realizar cambios."}, {"id": 154, "q": "En los diagramas con parte central en blanco…", "opts": {"A": "Las operaciones no se numeran de forma correlativa.", "B": "Las actividades se numeran de forma correlativa sin distinción de clase.", "C": "Las actividades de la misma clase se numeran correlativamente empezando por las del elemento principal.", "D": "La distancia se anota en una columna habilitada para ese efecto."}, "correct": "C", "tema": "General", "src": "Examen 2024", "exp": "En estos diagramas de montaje en blanco, la numeración de los símbolos (operaciones, inspecciones) se hace de forma independiente por clases y de derecha a izquierda (empezando por la línea del elemento principal)."}, {"id": 155, "q": "En la distribución en línea o por producto…", "opts": {"A": "Se requiere una alta cualificación profesional de la mano de obra directa.", "B": "Los puestos de trabajo se instalan con carácter provisional junto al elemento o conjunto que se fabrica o monta.", "C": "El incentivo a la mano de obra es por logro conjunto.", "D": "Se permite la adaptación inmediata a otra fabricación distinta de aquélla para la que fue proyectada."}, "correct": "C", "tema": "Normativa (CTE, incendios, seguridad)", "src": "Examen 2024", "exp": "Al estar los operarios encadenados en una línea de montaje, el ritmo lo marca la velocidad de la cinta. Por tanto, no se incentiva la velocidad individual (que generaría acumulación de stock), sino la productividad de toda la línea (logro conjunto)."}, {"id": 156, "q": "La economía neta actual.", "opts": {"A": "No considera la amortización.", "B": "No considera los intereses.", "C": "Es la economía bruta anual menos la amortización.", "D": "Equivale a la diferencia entre el valor de la m.o.d. del método actual y el valor de la m.o.d. del método propuesto."}, "correct": "C", "tema": "Evaluación económica", "src": "Examen 2024", "exp": "La economía neta es el ahorro real obtenido. Se calcula restando del ahorro bruto de mano de obra/materiales (economía bruta) la cuota de amortización (depreciación) de la maquinaria adquirida."}, {"id": 157, "q": "De acuerdo con la clasificación de las edificaciones del RD 2267/2004, en igualdad de condiciones, los requisitos mínimos de protección contra incendios son generalmente mayores para:", "opts": {"A": "Edificaciones tipo A.", "B": "Edificaciones tipo B.", "C": "Edificaciones tipo C, D y E.", "D": "Los requisitos son independientes de la edificación."}, "correct": "A", "tema": "Normativa (CTE, incendios, seguridad)", "src": "Examen 2024", "exp": "Las naves Tipo A comparten estructura y muros con naves colindantes. Al ser mayor el riesgo de propagación horizontal del incendio a los vecinos, el reglamento les impone las medidas más exigentes de estabilidad al fuego y sistemas de extinción."}, {"id": 158, "q": "¿En el contexto de la Protección contra incendios, si en una edificación industrial coexisten con la misma titularidad una zona administrativa con una superficie construida de 300 m? y una zona industrial con una superficie construida de 1200 m2:", "opts": {"A": "Será de aplicación al conjunto del edificio el RD 2267/2004, que aprueba el Reglamento de seguridad contra incendios en edificios industriales, al tratarse de un único edifico industrial.", "B": "Será de aplicación en la zona industrial el RD 2267/2004, que aprueba el Reglamento de seguridad contra incendios en edificios industriales, y en la zona administrativa el CTE DB SI, Seguridad contra incendios, al superar esta los 250 m.", "C": "Será de aplicación al conjunto del edificio el CTE DB SI, Seguridad contra incendios, al tratarse de una edificación, sea o no industrial.", "D": "Se podrán aplicar indistintamente una o ambas normas."}, "correct": "B", "tema": "Normativa (CTE, incendios, seguridad)", "src": "Examen 2024", "exp": "El RSCIEI establece que los sectores administrativos anexos a naves industriales se regulan por el Código Técnico (CTE DB SI) si su superficie construida es mayor de **250 m²**. En caso contrario, se evaluarían de forma simplificada por el propio RSCIEI."}];

// ====== Estado ======
const LS = 'proyectos_quiz_v1';
let store = load();
let temas = {};            // tema -> count
let selTemas = new Set();  // filtros activos
let S = null;              // sesión actual
let PENALTY = (store.penalty!=null ? store.penalty : 1/3);  // resta por fallo (4 opciones: 1/3 = neutral al azar)
const EXAM_N = 40;         // preguntas del examen real

function load(){
  try{ return JSON.parse(localStorage.getItem(LS)) || {}; }catch(e){ return {}; }
}
function save(){ try{ localStorage.setItem(LS, JSON.stringify(store)); }catch(e){} }
store.seen   = store.seen   || 0;
store.correct= store.correct|| 0;
store.fails  = store.fails  || [];      // ids fallados (pendientes)
store.best   = store.best   || null;    // mejor nota examen (0-10)

// ====== Util ======
const $ = id => document.getElementById(id);
function shuffle(a){ a=a.slice(); for(let i=a.length-1;i>0;i--){const j=(Math.random()*(i+1))|0;[a[i],a[j]]=[a[j],a[i]];} return a; }
function show(view){ ['home','quiz','result'].forEach(v=>$(v).classList.toggle('hide', v!==view)); window.scrollTo(0,0); }

// ====== Init ======
function init(){
  $('bankcount').textContent = BANK.length + ' preguntas';
  BANK.forEach(q=>{ temas[q.tema]=(temas[q.tema]||0)+1; });
  const chips = $('temachips');
  Object.entries(temas).sort((a,b)=>b[1]-a[1]).forEach(([t,n])=>{
    const c=document.createElement('div'); c.className='chip'; c.dataset.t=t;
    c.innerHTML = t + ' <span class="n">'+n+'</span>';
    c.onclick=()=>{ c.classList.toggle('on'); if(selTemas.has(t))selTemas.delete(t); else selTemas.add(t); };
    chips.appendChild(c);
  });
  renderStats();
  setPenalty(PENALTY);
}
function renderStats(){
  $('st-seen').textContent = store.seen;
  $('st-acc').textContent  = store.seen ? Math.round(store.correct/store.seen*100)+'%' : '—';
  $('st-fail').textContent = store.fails.length;
  $('st-best').textContent = store.best!=null ? store.best.toFixed(1).replace('.',',') : '—';
  $('failcount').textContent = store.fails.length ? '('+store.fails.length+' pendientes)' : '(ninguno aún)';
}
function resetStats(){
  if(!confirm('¿Reiniciar todo tu progreso y la lista de fallos?')) return;
  store={seen:0,correct:0,fails:[],best:null,penalty:PENALTY}; save(); renderStats();
}
function setPenalty(v){
  PENALTY=v; store.penalty=v; save();
  document.querySelectorAll('[data-pen]').forEach(el=>{
    el.classList.toggle('on', Math.abs(parseFloat(el.dataset.pen)-v)<0.01);
  });
}

// ====== Selección de preguntas ======
function pool(){
  let p = BANK;
  if(selTemas.size) p = p.filter(q=>selTemas.has(q.tema));
  return p;
}

// ====== Arranque de modos ======
function start(mode){
  if(S && S.timer){ clearInterval(S.timer); S.timer=null; }  // evita timers huérfanos
  let qs;
  if(mode==='fallos'){
    if(!store.fails.length){ alert('Aún no tienes preguntas falladas. Haz algún test primero 🙂'); return; }
    qs = shuffle(BANK.filter(q=>store.fails.includes(q.id)));
  } else if(mode==='examen'){
    const p=pool(); if(p.length<5){ alert('Pocas preguntas con ese filtro. Quita filtros.'); return; }
    qs = shuffle(p).slice(0, Math.min(EXAM_N,p.length));
  } else if(mode==='flash'){
    const p=pool(); qs = shuffle(p).slice(0,10);
  } else { // practica: barajado infinito
    qs = shuffle(pool());
  }
  S = { mode, qs, i:0, ok:0, no:0, blank:0, infinite: mode==='practica',
        answered:false, examWrong:[], byTema:{}, t0:Date.now(), timer:null, left: 90*60, penalty:PENALTY };
  show('quiz');
  $('q-hint').classList.toggle('hide', false);
  $('q-finish').classList.toggle('hide', mode!=='examen');
  // timer solo en examen
  if(mode==='examen'){ $('q-timer').classList.remove('hide'); startTimer(); }
  else $('q-timer').classList.add('hide');
  renderQ();
}

function startTimer(){
  tick();
  S.timer=setInterval(tick,1000);
  function tick(){
    const m=String(Math.floor(S.left/60)).padStart(2,'0'), s=String(S.left%60).padStart(2,'0');
    const el=$('q-timer'); el.textContent=m+':'+s;
    el.classList.toggle('warn', S.left<=300);
    if(S.left<=0){ clearInterval(S.timer); finishExam(); }
    S.left--;
  }
}

// ====== Render pregunta ======
function renderQ(){
  const q = S.qs[S.i];
  S.answered=false; S.shuffledKeys = shuffle(Object.keys(q.opts));
  $('q-tema').textContent = q.tema;
  const srcEl=$('q-src');
  if(q.src && q.src!=='banco'){ srcEl.textContent='⭐ '+q.src; srcEl.classList.remove('hide'); }
  else srcEl.classList.add('hide');

  const total = S.infinite ? '∞' : S.qs.length;
  $('q-count').textContent = (S.i+1)+' / '+total;
  $('q-bar').style.width = S.infinite ? ((S.i%20)/20*100)+'%' : ((S.i)/S.qs.length*100)+'%';
  $('q-text').textContent = q.q;

  const box=$('q-opts'); box.innerHTML='';
  S.shuffledKeys.forEach((k,idx)=>{
    const d=document.createElement('div'); d.className='opt'; d.dataset.k=k;
    d.innerHTML='<div class="k">'+'ABCD'[idx]+'</div><div>'+q.opts[k]+'</div>';
    d.onclick=()=>answer(k);
    box.appendChild(d);
  });
  $('q-feed').className='feedline'; $('q-feed').textContent='';
  $('q-expl').className='expl'; $('q-expl').innerHTML='';
  $('q-next').classList.add('hide');
  // botón "dejar en blanco": solo en examen y antes de responder
  $('q-blank').classList.toggle('hide', S.mode!=='examen');
  updateRun();
}

// Dejar en blanco (examen): 0 puntos, no cuenta como fallo
function skipBlank(){
  if(S.answered) return;
  S.answered=true; S.blank++;
  const q=S.qs[S.i];
  [...$('q-opts').children].forEach(el=>{
    el.classList.add('locked');
    if(el.dataset.k===q.correct) el.classList.add('correct'); else el.classList.add('dim');
  });
  const f=$('q-feed'); f.classList.add('show'); f.style.color='var(--muted)';
  f.textContent='⊘ En blanco — la correcta era '+letterLabel(q)+') (0 puntos, sin penalización)';
  if(q.exp){ const e=$('q-expl'); e.classList.add('show'); e.innerHTML='<b>¿Por qué?</b> '+q.exp; }
  S.byTema[q.tema]=S.byTema[q.tema]||{ok:0,n:0,blank:0}; S.byTema[q.tema].blank=(S.byTema[q.tema].blank||0)+1;
  $('q-blank').classList.add('hide');
  $('q-next').classList.remove('hide');
  updateRun();
}

// ====== Responder ======
function answer(k){
  if(S.answered) return;
  S.answered=true;
  const q=S.qs[S.i];
  const correct = (k===q.correct);
  // pintar
  [...$('q-opts').children].forEach(el=>{
    el.classList.add('locked');
    const ek=el.dataset.k;
    if(ek===q.correct) el.classList.add('correct');
    else if(ek===k) el.classList.add('wrong');
    else el.classList.add('dim');
  });
  // feedback
  const f=$('q-feed');
  f.classList.add('show', correct?'ok':'no');
  f.textContent = correct ? '✓ ¡Correcto!' : '✗ Incorrecto — la correcta es '+letterLabel(q)+')';
  // explicación
  if(q.exp){
    const e=$('q-expl'); e.classList.add('show');
    e.innerHTML='<b>¿Por qué?</b> '+q.exp;
  }
  // stats globales
  S.ok+=correct?1:0; S.no+=correct?0:1;
  store.seen++; if(correct) store.correct++;
  // lista de fallos
  if(!correct && !store.fails.includes(q.id)) store.fails.push(q.id);
  if(correct && S.mode==='fallos'){ store.fails = store.fails.filter(x=>x!==q.id); }
  // por tema (examen)
  S.byTema[q.tema]=S.byTema[q.tema]||{ok:0,n:0,blank:0}; S.byTema[q.tema].n++; if(correct)S.byTema[q.tema].ok++;
  if(!correct) S.examWrong.push(q.id);
  $('q-blank').classList.add('hide');
  save(); renderStats(); updateRun();
  // botón siguiente
  if(S.mode!=='examen') $('q-next').classList.remove('hide');
  // en examen avanza solo tras breve pausa visual? -> mostramos siguiente también
  if(S.mode==='examen') $('q-next').classList.remove('hide');
}
function letterLabel(q){
  // posición mostrada (A-D) de la opción correcta
  const idx=S.shuffledKeys.indexOf(q.correct);
  return 'ABCD'[idx];
}
function updateRun(){
  $('run-ok').textContent=S.ok; $('run-no').textContent=S.no;
  const t=S.ok+S.no; $('run-pct').textContent = t? Math.round(S.ok/t*100)+'%':'—';
}

// ====== Navegación ======
function nextQ(){
  if(!S.answered){ // permitir saltar sin responder en práctica
  }
  S.i++;
  if(S.infinite && S.i>=S.qs.length){ S.qs=shuffle(pool()); S.i=0; }   // recargar barajado infinito
  if(!S.infinite && S.i>=S.qs.length){ return finishExam(); }
  renderQ();
}
function quitQuiz(){
  if(S.timer) clearInterval(S.timer);
  if(S.mode==='practica' || S.mode==='fallos' || confirm('¿Salir del test?')){ goHome(); }
}
function goHome(){ if(S&&S.timer)clearInterval(S.timer); show('home'); renderStats(); }

// ====== Resultado examen / fin ======
function finishExam(){
  if(S.timer) clearInterval(S.timer);
  const total=S.qs.length, ok=S.ok, isExam=(S.mode==='examen');
  // Corrección con penalización (solo examen): puntos = aciertos - fallos*penalización
  const pen = isExam ? S.penalty : 0;
  const puntos = Math.max(0, ok - S.no*pen);
  const nota = total ? (puntos/total*10) : 0;
  if(isExam && (store.best==null || nota>store.best)){ store.best=nota; save(); }
  $('r-score').textContent = nota.toFixed(1).replace('.',',');
  if(isExam){
    const penTxt = pen>0.3 ? '⅓' : '¼';
    $('r-sub').innerHTML = ok+' aciertos · '+S.no+' fallos · '+S.blank+' en blanco<br>'+
      '<span style="font-size:13px">Neto: '+ok+' − '+S.no+'×'+penTxt+' = <b>'+puntos.toFixed(2).replace('.',',')+'</b> / '+total+'</span>';
  } else {
    $('r-sub').textContent = ok+' de '+total+' correctas';
  }
  const v=$('r-verdict');
  if(nota>=5){ v.className='verdict pass'; v.textContent='APROBADO ✓'; }
  else if(nota>=4){ v.className='verdict pass'; v.textContent='¡4 alcanzado! Liberas el tipo test ✓'; }
  else { v.className='verdict fail'; v.textContent='Aún no llegas al 4 — sigue practicando'; }
  $('r-ok').textContent=ok; $('r-no').textContent=S.no;
  const secs=Math.round((Date.now()-S.t0)/1000);
  $('r-time').textContent = Math.floor(secs/60)+'m '+(secs%60)+'s';
  $('r-pct').textContent = total?Math.round(ok/total*100)+'%':'—';
  // desglose por tema
  const tb=$('r-themes'); tb.innerHTML='';
  const ent=Object.entries(S.byTema).sort((a,b)=>b[1].n-a[1].n);
  if(ent.length){
    $('r-breakdown').classList.remove('hide');
    ent.forEach(([t,o])=>{
      const pct=Math.round(o.ok/o.n*100);
      const col = pct>=70?'var(--good)':pct>=50?'var(--warn)':'var(--bad)';
      const row=document.createElement('div');
      row.style.cssText='display:flex;align-items:center;gap:10px;margin:8px 0;font-size:13.5px';
      row.innerHTML='<span style="flex:1">'+t+'</span>'+
        '<span style="color:'+col+';font-weight:700">'+o.ok+'/'+o.n+' ('+pct+'%)</span>';
      tb.appendChild(row);
    });
  } else $('r-breakdown').classList.add('hide');
  $('r-review').classList.toggle('hide', S.examWrong.length===0);
  S._lastMode=S.mode;
  show('result');
}
function reviewFails(){ start('fallos'); }
function repeatMode(){ start(S._lastMode||'practica'); }

// ====== Delegación de eventos (CSP: sin onclick inline) ======
function dispatch(act){
  if(!act) return;
  const [cmd,arg]=act.split(':');
  switch(cmd){
    case 'start': start(arg); break;
    case 'pen':   setPenalty(parseFloat(arg)); break;
    case 'reset': resetStats(); break;
    case 'blank': skipBlank(); break;
    case 'quit':  quitQuiz(); break;
    case 'next':  nextQ(); break;
    case 'finish':finishExam(); break;
    case 'home':  goHome(); break;
    case 'review':reviewFails(); break;
    case 'repeat':repeatMode(); break;
  }
}
document.addEventListener('click',e=>{
  const t=e.target.closest('[data-act]');
  if(t) dispatch(t.dataset.act);
});

// ====== Teclado ======
document.addEventListener('keydown',e=>{
  if($('quiz').classList.contains('hide')) return;
  const k=e.key.toUpperCase();
  if(!S.answered){
    if((k==='0' || k==='B') && S.mode==='examen'){ e.preventDefault(); return skipBlank(); }
    let idx=-1;
    if('1234'.includes(k)) idx=+k-1;
    else if('ABCD'.includes(k)) idx='ABCD'.indexOf(k);
    if(idx>=0 && idx<S.shuffledKeys.length){ e.preventDefault(); answer(S.shuffledKeys[idx]); }
  } else if(e.key==='Enter' || e.key===' '){
    e.preventDefault();
    if(S.mode==='examen' && S.i>=S.qs.length-1) finishExam(); else nextQ();
  }
});

init();
